from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color and (r,c) not in seen:
          q=[(r,c)]; seen.add((r,c)); cells=[]
          while q:
            x,y=q.pop(); cells.append((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
              z=(x+dx,y+dy)
              if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==color:
                seen.add(z); q.append(z)
          comps.append([color,cells])
    comps.sort(key=lambda x:max(c for r,c in x[1]),reverse=True)
    placed=[]
    for color,cells in comps:
      cells=set(cells)
      while True:
        nxt={(r,c+1) for r,c in cells}
        if any(c>=w for r,c in nxt) or any(nxt & other for _,other in placed): break
        cells=nxt
      placed.append((color,cells))
    out=[[0]*w for _ in range(h)]
    for color,cells in placed:
      for r,c in cells: out[r][c]=color
    return out

